contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: amount to send with Put, lockTime to pass to Put
    function run(uint putAmount, uint lockTime) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        // ensure this test contract can fund the Put call
        require(address(this).balance >= putAmount);

        // read observable before-values
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // attempt Put and capture whether it reverted
        bool putReverted;
        c.Put{value: putAmount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            putReverted = true;
        } else {
            putReverted = false;
        }

        // read observable after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General invariant: if Put did not revert then stored balance did not decrease and contract balance did not decrease; moreover the increase in stored balance is <= increase in contract balance (contract must hold at least as much extra ETH as recorded).
        assert( putReverted || (afterBal >= beforeBal && afterContractBal >= beforeContractBal && (afterBal - beforeBal) <= (afterContractBal - beforeContractBal)) );
    }

    receive() external payable {}
}

