// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putAmount, uint256 lockTime) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        uint256 beforeUnlock;
        uint256 beforeBal;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBal = __r1; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool putReverted;
        try c.Put{value: putAmount}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }
        uint256 afterUnlock;
        uint256 afterBal;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBal = __r1; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(putReverted || (afterBal >= beforeBal && afterContractBal >= beforeContractBal && (afterBal - beforeBal) <= (afterContractBal - beforeContractBal)));
    }

    function testFuzz_run(uint256 putAmount, uint256 lockTime) public {
        _run(putAmount, lockTime);
    }

    receive() external payable {}
}
